#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }
    vector<int> part1, part2;
    int half = n / 2;

    function<void(int, int)> generate_sums1 = [&](int index, int total) {
        if (index == half) {
            part1.push_back(total);
        } else {
            generate_sums1(index + 1, (total + a[index]) % m);
            generate_sums1(index + 1, total);
        }
    };

    function<void(int, int)> generate_sums2 = [&](int index, int total) {
        if (index == n) {
            part2.push_back(total);
        } else {
            generate_sums2(index + 1, (total + a[index]) % m);
            generate_sums2(index + 1, total);
        }
    };

    generate_sums1(0, 0);
    generate_sums2(half, 0);

    sort(part1.begin(), part1.end());

    int max_sum = 0;
    for (int val : part2) {
        int idx = (int)(std::lower_bound(part1.begin(), part1.end(), m - val) - part1.begin());
        if (idx > 0) {
            int candidate = part1[idx - 1] + val;
            if (candidate > max_sum) {
                max_sum = candidate;
            }
        }
    }
    cout << max_sum << "\n";
    return 0;
}
